// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _lockTime, uint256 _am) public {
        // Bound inputs to reasonable ranges
        _val = bound(_val, 0, 1000);
        _lockTime = bound(_lockTime, 0, 100);
        _am = bound(_am, 0, 1000);

        // Set MinSum before initialization
        c.SetMinSum(_val);
        // Initialize the contract
        c.Initialized();
        // Now try to call Collect (this should not change MinSum)
        // Provide some value so the contract has balance to potentially collect
        vm.deal(address(c), 1000);
        vm.deal(address(this), 1000);
        (bool success, ) = address(c).call{value: 0}(""); // Just to have some balance in accounts
        // Now call Collect with given amount
        c.Collect(_am);
        // The rule: MinSum should equal the set value (_val) and never change
        assertTrue(c.MinSum() == _val, "MinSum should remain equal to the value set before initialization");
    }
}

